////////////////////////////////////////////////////////////
#include "Zancle/HasBuiltin.hpp"


#if ZA_HAS_BUILTIN(__is_constructible) && ZA_HAS_BUILTIN(__add_lvalue_reference)

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include "Zancle/Trait/AddConst.hpp"


    ////////////////////////////////////////////////////////////
    #define ZA_IS_COPY_CONSTRUCTIBLE(...) \
        __is_constructible(__VA_ARGS__, __add_lvalue_reference(::za::AddConst<__VA_ARGS__>))

#else

////////////////////////////////////////////////////////////
// Headers
////////////////////////////////////////////////////////////
    #include <type_traits>


    ////////////////////////////////////////////////////////////
    #define ZA_IS_COPY_CONSTRUCTIBLE(...) ::std::is_copy_constructible_v<__VA_ARGS__>

#endif


namespace za
{
////////////////////////////////////////////////////////////
template <typename T>
inline constexpr bool isCopyConstructible = ZA_IS_COPY_CONSTRUCTIBLE(T);

} // namespace za
